import sys
import json
import pandas as pd
import numpy as np

def to_float(x):
    return float(x) if x is not None and not pd.isna(x) else None

def fmt_value(metric, period, value):
    if value is None or pd.isna(value):
        return None
    v = float(value)
    if period in ("WoW", "YoY"):
        return round(v, 1)
    if metric == "revenue":
        return round(v, 2)
    if metric == "share":
        return round(v, 1)
    if metric == "rank":
        return round(v, 0)
    return round(v, 2)

def main():
    path = sys.argv[1]
    df = pd.read_csv(path)

    facts = []

    def add(entity, metric, period, value, formula):
        val = fmt_value(metric, period, value)
        if val is None:
            return
        facts.append({
            "entity": entity,
            "metric": metric,
            "period": period,
            "value": val,
            "formula": formula
        })

    # ---------- TOTAL facts ----------
    rev_tw = df["Revenue_TW"].sum(skipna=True)
    rev_lw = df["Revenue_LW"].sum(skipna=True)
    has_ly = df["Revenue_LY"].notna().any()
    rev_ly = df["Revenue_LY"].sum(skipna=True) if has_ly else None

    units_tw = df["Units_TW"].sum(skipna=True)
    units_lw = df["Units_LW"].sum(skipna=True)
    orders_tw = df["Orders_TW"].sum(skipna=True)
    orders_lw = df["Orders_LW"].sum(skipna=True)

    add("TOTAL", "revenue", "TW", rev_tw, "sum(Revenue_TW)")
    add("TOTAL", "revenue", "LW", rev_lw, "sum(Revenue_LW)")
    if has_ly:
        add("TOTAL", "revenue", "LY", rev_ly, "sum(Revenue_LY)")

    if rev_lw not in (0, None) and not pd.isna(rev_lw):
        wow_total = (rev_tw - rev_lw) / rev_lw * 100
        add("TOTAL", "revenue", "WoW", wow_total,
            "(sum(Revenue_TW) - sum(Revenue_LW)) / sum(Revenue_LW) * 100")

    if has_ly and rev_ly not in (0, None) and not pd.isna(rev_ly):
        yoy_total = (rev_tw - rev_ly) / rev_ly * 100
        add("TOTAL", "revenue", "YoY", yoy_total,
            "(sum(Revenue_TW) - sum(Revenue_LY)) / sum(Revenue_LY) * 100")

    add("TOTAL", "units", "TW", units_tw, "sum(Units_TW)")
    add("TOTAL", "units", "LW", units_lw, "sum(Units_LW)")
    if units_lw not in (0, None) and not pd.isna(units_lw):
        wow_units = (units_tw - units_lw) / units_lw * 100
        add("TOTAL", "units", "WoW", wow_units,
            "(sum(Units_TW) - sum(Units_LW)) / sum(Units_LW) * 100")

    add("TOTAL", "orders", "TW", orders_tw, "sum(Orders_TW)")
    add("TOTAL", "orders", "LW", orders_lw, "sum(Orders_LW)")
    if orders_lw not in (0, None) and not pd.isna(orders_lw):
        wow_orders = (orders_tw - orders_lw) / orders_lw * 100
        add("TOTAL", "orders", "WoW", wow_orders,
            "(sum(Orders_TW) - sum(Orders_LW)) / sum(Orders_LW) * 100")

    # ---------- Per-entity facts, sorted by Revenue_TW descending ----------
    df_sorted = df.sort_values("Revenue_TW", ascending=False, na_position="last")

    for _, row in df_sorted.iterrows():
        if len(facts) >= 25:
            break
        entity = row["Entity"]

        if len(facts) < 25 and not pd.isna(row.get("Revenue_TW", np.nan)):
            add(entity, "revenue", "TW", row["Revenue_TW"], "Revenue_TW")
        if len(facts) < 25 and not pd.isna(row.get("Share_Pct", np.nan)):
            add(entity, "share", "TW", row["Share_Pct"], "Share_Pct")
        if len(facts) < 25 and not pd.isna(row.get("Rank", np.nan)):
            add(entity, "rank", "TW", row["Rank"], "Rank")
        if len(facts) < 25 and not pd.isna(row.get("WoW_Pct", np.nan)):
            add(entity, "revenue", "WoW", row["WoW_Pct"],
                "(Revenue_TW - Revenue_LW) / Revenue_LW * 100")
        if len(facts) < 25 and not pd.isna(row.get("YoY_Pct", np.nan)):
            add(entity, "revenue", "YoY", row["YoY_Pct"],
                "(Revenue_TW - Revenue_LY) / Revenue_LY * 100")
        if len(facts) < 25 and not pd.isna(row.get("Revenue_LW", np.nan)):
            add(entity, "revenue", "LW", row["Revenue_LW"], "Revenue_LW")
        if len(facts) < 25 and not pd.isna(row.get("Revenue_LY", np.nan)):
            add(entity, "revenue", "LY", row["Revenue_LY"], "Revenue_LY")

    facts = facts[:25]

    print(json.dumps(facts))

if __name__ == "__main__":
    main()
